/**
 * eMAG campaign calendar. The strip picks the active campaign (or the next
 * upcoming one) automatically from today's date.
 *
 * `campaigns.json` is generated by scripts/sync-campaigns.mjs from the
 * Profitshare API (daily via .github/workflows/sync-campaigns.yml), with tracked
 * affiliate links; the strip then refreshes it live from /api/campaigns.
 * `manual` is only for campaigns eMAG has announced but not yet published to
 * Profitshare; a manual entry is dropped once a synced campaign overlaps its
 * dates (the strip repeats this merge for the live list).
 */
import synced from './campaigns.json';

export interface Campaign {
  name: string;
  start: string; // YYYY-MM-DD
  end: string; // YYYY-MM-DD (inclusive)
  url: string;
}

export const manual: Campaign[] = [
  { name: 'Black Friday', start: '2026-11-06', end: '2026-11-16', url: 'https://l.profitshare.ro/l/16749081' },
];

export const campaigns: Campaign[] = [
  ...synced,
  ...manual.filter((m) => !synced.some((s) => s.start <= m.end && s.end >= m.start)),
];
